# GENERATED by prepare_power_reset_checks.py; ancestors unchanged.
"""Record native KiCad ERC violations of the partial NET-18 sheet, no waivers."""
import hashlib
import json
from pathlib import Path
import subprocess
from build_power_reset import ROOT,OUT,VERIFY,KICAD


def main():
    cmd=[KICAD,'sch','erc','--format','json','--severity-all','--exit-code-violations',
         '-o',str(VERIFY/'erc.json'),str(OUT/'power_reset.kicad_sch')]
    r=subprocess.run(cmd,capture_output=True,text=True)
    raw=json.loads((VERIFY/'erc.json').read_text());counts={}
    for sheet in raw.get('sheets',[]):
        for x in sheet.get('violations',[]):counts[x['type']]=counts.get(x['type'],0)+1
    report={'date':'2026-11-26','kicad':subprocess.check_output([KICAD,'version'],text=True).strip(),
      'command':cmd,'exit':r.returncode,'stdout':r.stdout,'stderr':r.stderr,'violation_counts':counts,
      'sources':[{'path':p.relative_to(ROOT).as_posix(),'sha256':hashlib.sha256(p.read_bytes()).hexdigest()}
                 for p in [OUT/'power_reset.kicad_sch',OUT/'power_reset.kicad_pro',OUT/'bus_packages.kicad_sym',Path(__file__)]],
      'erc_passed':r.returncode==0,'board_release':False,'scope':'Partial sheet; inputs/outputs/power sources need global union, no waivers added'}
    (VERIFY/'erc-summary.json').write_text(json.dumps(report,indent=2)+'\n')
    cmd=[KICAD,'sch','export','pdf','-o',str(VERIFY/'power_reset.pdf'),str(OUT/'power_reset.kicad_sch')]
    subprocess.run(cmd,check=True,capture_output=True)
    subprocess.run(['pdftoppm','-scale-to','1800','-png','-singlefile',str(VERIFY/'power_reset.pdf'),str(VERIFY/'preview')],check=True)
    print(json.dumps(report));return r.returncode


if __name__=='__main__':raise SystemExit(main())
